kit.scene('honour', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'honour', back: '<rect width="918" height="1027" style="fill:var(--accent);opacity:.18"/><g style="opacity:.25">' + W.lace(858, 140, 858, 960, 16, 8) + '</g>',
      cast: [{ who: 'ravana', x: 570, y: 1740, s: 1.38 }],
      cam: [1.0, 1.05, 455, 520, 446, 508],
      arm: (t, i, talk) => 26 + 7 * Math.sin(t * 1.3),
      lines: [[65.0, 67.3, 'नाना जी, प्राण बचाना बुरा नहीं…', 0, 0], [67.8, 70.0, 'पर सम्मान बेचकर जीना कैसा जीना?', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
